const useCatalyst = () => {
  const {
    selectedAccountId,
    accountSettings
  } = useSelectedAccount();
  const rewardInfo = accountSettings.rewardInfo;
  const hasCatalystData = accountSettings.hasCatalystData;
  const catalystData = accountSettings.catalystData;
  const isStakeKeyRegistered = computed(() => rewardInfo.value?.registered ?? false);
  const title = ref("");
  const text = ref("");
  const update = () => {
    title.value = "";
    text.value = "";
    if (networkId.value !== "mainnet" && networkId.value !== "preprod") {
      title.value = "wrongnetwork.title";
      text.value = "wrongnetwork.text";
      return;
    }
    if (!isStakeKeyRegistered.value) {
      title.value = "registration.nostake.title";
      text.value = "registration.nostake.text";
      return;
    }
    if (!hasCatalystData.value) {
      title.value = "registration.nocatalyst.title";
      text.value = "registration.nocatalyst.text";
      return;
    }
    title.value = "registration.hascatalyst.title";
    text.value = "registration.hascatalyst.text";
  };
  watch(rewardInfo, () => {
    update();
  }, { deep: true });
  watch([isStakeKeyRegistered, selectedAccountId], () => {
    update();
  }, { immediate: true });
  return {
    selectedAccountId,
    isStakeKeyRegistered,
    hasCatalystData,
    catalystData,
    statusTitle: title,
    statusText: text
  };
};

